import json,sys;from sakura_knowledge.api import Knowledge
try:
 with Knowledge(sys.argv[1]) as k:
  op=sys.argv[2];a=json.loads(sys.argv[3])
  if op=='lookup_key': v=k.lookup(key={x:a[x] for x in ('kind','namespace','value')})
  elif op=='related': v=k.related({x:a[x] for x in ('kind','namespace','value')},relation=a.get('relation'),kind=a.get('kind_filter'),limit=a.get('limit',20))
  else: v=getattr(k,op)(**a)
  print(json.dumps(v,ensure_ascii=False,separators=(',',':')))
except Exception as e:
 print(json.dumps({'error':type(e).__name__,'message':str(e)}),file=sys.stderr);sys.exit(2)

